<?php $showStoreFooter=false; require_once dirname(__DIR__).'/partials/handoff_art.php'; ?><section class="account-shell"><?php require dirname(__DIR__).'/partials/account_navigation.php'; ?><div class="account-main orders-main"><?php $statusLabels=['pending'=>'Order confirmed','processing'=>'Preparing','shipped'=>'Dispatched','delivered'=>'Delivered','cancelled'=>'Cancelled']; ?>
<header class="account-section-heading"><h1>Orders</h1></header>
<form class="collection-filters" method="get" action="<?= e(url('/orders')) ?>" data-auto-collection="orders" role="search"><label class="field"><span>Search orders</span><input type="search" name="q" maxlength="60" value="<?= e($history['q']) ?>" placeholder="Order number or product name"></label><label class="field"><span>Status</span><select name="status"><option value="">All orders</option><?php foreach($statusLabels as $value=>$label): ?><option value="<?= e($value) ?>" <?= $history['status']===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><noscript><button class="btn btn-secondary" type="submit">Search</button></noscript></form>
<div data-collection-view="orders"><p class="muted small" data-order-result-count><?= (int)$history['total'] ?> matching <?= (int)$history['total']===1?'order':'orders' ?></p>
<?php if(!$history['items']): $emptyTitle='No orders to show';$emptyMessage=$history['status']!==''||$history['q']!==''?'Try another order number or status.':'Your orders will appear here after your first purchase.';$emptyActionLabel='Browse products';$emptyActionUrl=url('/shop');require dirname(__DIR__).'/partials/empty_state.php'; else: ?>
<div class="order-history-list" data-continuous-list="orders" data-stream-page="<?= (int)$history['page'] ?>" data-next-url="<?= e($history['page']<$history['pages']?url('/orders?'.http_build_query(['q'=>$history['q'],'status'=>$history['status'],'page'=>$history['page']+1])):'') ?>"><?php foreach($history['items'] as $item): ?><article data-stream-key="order-<?= (int)$item['id'] ?>" class="order-history-card" aria-labelledby="order-title-<?= (int)$item['id'] ?>"><div class="order-card-heading"><div><h2 id="order-title-<?= (int)$item['id'] ?>"><?= e(\App\Services\OrderReference::display($item)) ?></h2><p><?= e(date('j F Y',strtotime($item['created_at']))) ?></p></div><span class="order-status-badge"><?= e(\App\Services\OrderProgress::label($item)) ?></span></div>
<div class="order-card-products"><div class="order-product-thumbs"><?php foreach(array_slice($item['items'],0,3) as $product): $image=product_image_url($product['image_path']??null); ?><img src="<?= e($image??product_placeholder_url('')) ?>" alt="<?= e($product['product_name_snapshot']) ?>" width="64" height="64" loading="lazy"><?php endforeach; ?></div><div class="order-preview-copy"><span><?= (int)$item['item_count'] ?> <?= (int)$item['item_count']===1?'item':'items' ?></span><p><?= e(implode(' · ',array_column(array_slice($item['items'],0,2),'product_name_snapshot'))) ?><?php if(count($item['items'])>2): ?> · and <?= count($item['items'])-2 ?> more<?php endif; ?></p></div></div>
<dl class="order-card-meta"><div><dt>Payment method</dt><dd><?= $item['payment_method']==='cod'?'Cash on delivery':($item['maya_state']!==null?'Debit/Credit Card':'Payment on arrangement') ?></dd></div><div><dt>Payment status</dt><dd><?= e(\App\Services\OrderPaymentStatus::label($item)) ?></dd></div></dl>
<div class="order-card-footer"><div class="order-card-total"><small>Order total</small><strong>₱<?= e(number_format((float)$item['total'],2)) ?></strong></div><a class="btn btn-secondary btn-sm" href="<?= e(url('/orders/view?'.http_build_query(!empty($item['public_reference'])?['reference'=>$item['public_reference']]:['id'=>(int)$item['id']]))) ?>">View order </a></div></article><?php endforeach; ?></div>
<?php $moreUrl=$history['page']<$history['pages']?url('/orders?'.http_build_query(['q'=>$history['q'],'status'=>$history['status'],'page'=>$history['page']+1])):'';if($moreUrl||(int)$history['page']>1) require dirname(__DIR__).'/partials/continuous_status.php'; ?>
<?php endif; ?>

</div>
</div></section>